type ModelViewerView = "front" | "side" | "back" | "three-quarter"

type Vec3 = readonly [number, number, number]

/** A sphere around what to frame, in the model's own units, like a face for a close-up. */
type ModelViewerBounds = { center: Vec3; radius: number }

type ModelViewerFraming = "full" | ModelViewerBounds

/** Where the camera sits around its target: degrees around the vertical axis and above the horizon, and a zoom. */
type ModelViewerOrbit = { yaw: number; pitch: number; zoom: number }

const modelViewerViews: readonly ModelViewerView[] = ["front", "three-quarter", "side", "back"]

// A glTF model faces +Z, so yaw 0 looks at its front; the three-quarter view turns a little and looks a little down.
const viewAngles: Record<ModelViewerView, { yaw: number; pitch: number }> = {
  front: { yaw: 0, pitch: 0 },
  "three-quarter": { yaw: 35, pitch: 8 },
  side: { yaw: 90, pitch: 0 },
  back: { yaw: 180, pitch: 0 },
}

const pitchRange = [-60, 75] as const
const zoomRange = [0.5, 3] as const
const fieldOfView = 30
// Room left around a framed model, as a share of the view.
const framingMargin = 1.1

const clampNumber = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, Number.isFinite(value) ? value : min))

const clampPitch = (pitch: number) => clampNumber(pitch, pitchRange[0], pitchRange[1])
const clampZoom = (zoom: number) => clampNumber(zoom, zoomRange[0], zoomRange[1])

/** The same angle in (-180, 180]. */
function wrapDegrees(angle: number) {
  const wrapped = ((((angle + 180) % 360) + 360) % 360) - 180
  return wrapped === -180 ? 180 : wrapped
}

/** `to`, moved by whole turns to within half a turn of `from`, so a tween takes the short way round. */
function nearestAngle(from: number, to: number) {
  return from + wrapDegrees(to - from)
}

/**
 * Frame-rate independent easing: how far `current` gets toward `target` after `dt` seconds, at `rate` per second
 * (about 1/rate seconds to cover two thirds of the way).
 */
function damp(current: number, target: number, rate: number, dt: number) {
  return target + (current - target) * Math.exp(-rate * Math.max(0, dt))
}

const settleEpsilon = 1e-3

type WeightMap = Readonly<Record<string, number>>

/**
 * One step of morph weights toward their targets. Names missing from `target` ease back to 0. Returns the new
 * weights and whether every one has arrived, so the caller stops asking for frames.
 */
function dampWeights(current: WeightMap, target: WeightMap, rate: number, dt: number) {
  const next: Record<string, number> = {}
  let settled = true
  for (const name of new Set([...Object.keys(current), ...Object.keys(target)])) {
    const goal = clampNumber(target[name] ?? 0, 0, 1)
    const value = damp(current[name] ?? 0, goal, rate, dt)
    const arrived = Math.abs(value - goal) < settleEpsilon
    next[name] = arrived ? goal : value
    if (!arrived) settled = false
  }
  return { next, settled }
}

/** The camera's position around `target`, `distance` away, for a yaw and pitch in degrees. */
function orbitPosition(target: Vec3, yaw: number, pitch: number, distance: number): Vec3 {
  const y = (yaw * Math.PI) / 180
  const p = (pitch * Math.PI) / 180
  return [
    target[0] + distance * Math.sin(y) * Math.cos(p),
    target[1] + distance * Math.sin(p),
    target[2] + distance * Math.cos(y) * Math.cos(p),
  ]
}

const halfTan = (fov: number) => Math.tan(((fov / 2) * Math.PI) / 180)

/**
 * How far a camera with a vertical `fov` (degrees) and `aspect` (width over height) stands from a box's centre to
 * see all of its `width` × `height` face, with the margin around it, standing in front of its `depth`.
 */
function fitBoxDistance(size: Vec3, fov: number, aspect: number) {
  const [width, height, depth] = size
  const vertical = (height * framingMargin) / 2 / halfTan(fov)
  const horizontal = (width * framingMargin) / 2 / (halfTan(fov) * aspect)
  return Math.max(vertical, horizontal) + depth / 2
}

/** The distance that fits a sphere of `radius`, with the margin, in the narrower side of the view. */
function fitSphereDistance(radius: number, fov: number, aspect: number) {
  return (radius * framingMargin) / (halfTan(fov) * Math.min(1, aspect))
}

/** The world size of the view at `distance` from a camera with a vertical `fov` and `aspect`. */
function viewSizeAt(distance: number, fov: number, aspect: number) {
  const height = 2 * distance * halfTan(fov)
  return { width: height * aspect, height }
}

/** The size an image of `ratio` (width over height) takes drawn with `object-fit: contain` in a box. */
function containSize(ratio: number, box: { width: number; height: number }) {
  return box.width / box.height > ratio
    ? { width: box.height * ratio, height: box.height }
    : { width: box.width, height: box.width / ratio }
}

export {
  clampNumber,
  clampPitch,
  clampZoom,
  containSize,
  damp,
  dampWeights,
  fieldOfView,
  fitBoxDistance,
  fitSphereDistance,
  framingMargin,
  modelViewerViews,
  nearestAngle,
  orbitPosition,
  pitchRange,
  viewAngles,
  viewSizeAt,
  wrapDegrees,
  zoomRange,
}
export type { ModelViewerBounds, ModelViewerFraming, ModelViewerOrbit, ModelViewerView, Vec3, WeightMap }

import {
  announce,
  createChange,
  definePrimitive,
  prepareAnnouncements,
  type ChangeDetails,
  type TypesOf,
} from "@ui-sdk/core"

import {
  clampPitch,
  clampZoom,
  modelViewerViews,
  nearestAngle,
  viewAngles,
  wrapDegrees,
  type ModelViewerView,
} from "@/components/ui/model-viewer-math"

/** `unsupported`: the browser has no WebGL, so the poster and a message stand in. */
type ModelViewerStatus = "idle" | "loading" | "ready" | "error" | "unsupported"

/** A press on a control, a choice in the clip list, a key on the stage, a drag or pinch, or a call (an agent, a controller). */
type ModelViewerChangeReason = "trigger-press" | "input-change" | "keyboard" | "drag" | "imperative"

type ModelViewerMotion = "tween" | "jump"

type ModelViewerOptions = {
  view?: ModelViewerView | null
  defaultView?: ModelViewerView
  onViewChange?: (view: ModelViewerView | null, details: ChangeDetails<ModelViewerChangeReason>) => void
  clip?: string | null
  defaultClip?: string | null
  onClipChange?: (clip: string | null, details: ChangeDetails<ModelViewerChangeReason>) => void
  /** Leave it out, or null, to play once loaded, except under reduced motion. */
  playing?: boolean | null
  defaultPlaying?: boolean
  onPlayingChange?: (playing: boolean | null, details: ChangeDetails<ModelViewerChangeReason>) => void
  /** Drag, pinch, wheel and keys move the camera. */
  interactive?: boolean
  /** Loads the scene once the stage nears the viewport; false holds it back. */
  load?: boolean
  errorMessage?: string
}

// Rotation per arrow press and per CSS pixel dragged, in degrees, and the zoom factor per step.
const keyStep = 15
const dragStep = 0.4
const zoomStep = 1.25

let webgl: boolean | undefined

/** Whether this browser can draw WebGL, asked once per page. */
function supportsWebGL(doc: Document) {
  if (webgl !== undefined) return webgl
  const canvas = doc.createElement("canvas")
  const context = canvas.getContext("webgl2") ?? canvas.getContext("webgl")
  webgl = context !== null
  context?.getExtension("WEBGL_lose_context")?.loseContext()
  return webgl
}

type ModelViewerControlsState = {
  status: ModelViewerStatus
  view: ModelViewerView | null
  clips: readonly string[]
  /** The clip that plays: the chosen one, or the model's first. */
  clip: string | null
  playing: boolean
}

const reasonOf = (event: Event | undefined, fallback: ModelViewerChangeReason): ModelViewerChangeReason =>
  event ? fallback : "imperative"

const zoomKeys: Record<string, number> = { "+": 1, "=": 1, "-": -1, _: -1 }

const modelViewer = definePrimitive({
  name: "model-viewer",
  options: {
    view: "value",
    defaultView: "string",
    onViewChange: "callback",
    clip: "value",
    defaultClip: "value",
    onClipChange: "callback",
    playing: "boolean",
    defaultPlaying: "boolean",
    onPlayingChange: "callback",
    interactive: "boolean",
    load: "boolean",
    errorMessage: "string",
  },
  controlled: ["view", "clip", "playing"],
  live: ["yaw", "pitch", "zoom", "motion", "turn", "dragging"],
  state: (options: ModelViewerOptions) => {
    const view = options.view === undefined ? (options.defaultView ?? "front") : options.view
    const angles = viewAngles[view ?? "front"]
    return {
      view,
      yaw: angles.yaw,
      pitch: angles.pitch,
      zoom: 1,
      motion: "jump" as ModelViewerMotion,
      // Counts camera moves, so the scene can tell a new one from a repeat of the same angles.
      turn: 0,
      dragging: false,
      clip: options.clip ?? options.defaultClip ?? null,
      clips: [] as readonly string[],
      // null until someone chooses: the scene then plays unless motion is reduced.
      playing: (options.playing ?? options.defaultPlaying ?? null) as boolean | null,
      status: "idle" as ModelViewerStatus,
      reducedMotion: false,
      inView: false,
      pageHidden: false,
      seen: false,
      interactive: options.interactive ?? true,
      load: options.load ?? true,
    }
  },
  sync: (options) => ({
    interactive: options.interactive ?? true,
    load: options.load ?? true,
    ...(options.view === undefined ? {} : { view: options.view }),
    ...(options.clip === undefined ? {} : { clip: options.clip }),
    ...(options.playing === undefined ? {} : { playing: options.playing }),
  }),
  api: (context) => {
    const { store } = context
    const change = createChange(context)

    const move = (camera: { yaw?: number; pitch?: number; zoom?: number }, motion: ModelViewerMotion) => {
      const state = store.get()
      store.set({
        yaw: camera.yaw ?? state.yaw,
        pitch: clampPitch(camera.pitch ?? state.pitch),
        zoom: clampZoom(camera.zoom ?? state.zoom),
        motion: state.reducedMotion ? "jump" : motion,
        turn: state.turn + 1,
      })
    }
    const aim = (view: ModelViewerView, motion: ModelViewerMotion = "tween") => {
      const angles = viewAngles[view]
      const zoom = motion === "jump" ? { zoom: 1 } : {}
      move({ yaw: nearestAngle(store.get().yaw, angles.yaw), pitch: angles.pitch, ...zoom }, motion)
    }

    // A view set by a press, a prop or an agent turns the camera to it; free rotation clears the view.
    let aimed = store.get().view
    const unsubscribe = store.subscribe(() => {
      const { view } = store.get()
      if (view === aimed) return
      aimed = view
      if (view) aim(view)
    })
    context.onDestroy(unsubscribe)

    const loadedClips = (action: string) => {
      const { clips, status } = store.get()
      if (status !== "ready") throw new Error(`${action} works once the model has loaded (status: ${status}).`)
      if (clips.length === 0) throw new Error(`${action} needs an animation clip, and this model has none.`)
      return clips
    }
    const ready = (action: string) => {
      const { status } = store.get()
      if (status !== "ready") throw new Error(`${action} works once the model has loaded (status: ${status}).`)
    }
    const freeView = (reason: ModelViewerChangeReason, event?: Event) => {
      if (store.get().view !== null) change("view", null, { reason, event })
    }

    const api = {
      /** Turns the camera around the model by degrees: positive yaw turns the model right, positive pitch looks down on it. */
      rotate(yaw: number, pitch = 0, event?: Event) {
        ready("rotate")
        const state = store.get()
        freeView(reasonOf(event, "keyboard"), event)
        move({ yaw: state.yaw - yaw, pitch: state.pitch + pitch }, event?.type === "pointermove" ? "jump" : "tween")
        return true
      },
      /** Zooms in by steps (negative steps zoom out), each a factor of 1.25. */
      zoom(steps: number, event?: Event) {
        ready("zoom")
        move({ zoom: store.get().zoom * zoomStep ** steps }, event?.type === "keydown" ? "tween" : "jump")
        return true
      },
      /** Back to the first view and zoom. */
      reset(event?: Event) {
        ready("reset")
        const view = context.options().defaultView ?? "front"
        change("view", view, { reason: reasonOf(event, "trigger-press"), event })
        const angles = viewAngles[view]
        move({ yaw: nearestAngle(store.get().yaw, angles.yaw), pitch: angles.pitch, zoom: 1 }, "tween")
        return true
      },
      /** Turns to a named view: front, three-quarter, side or back. */
      setView(view: ModelViewerView, event?: Event) {
        if (!modelViewerViews.includes(view)) {
          throw new Error(`No view "${String(view)}". Views: ${modelViewerViews.join(", ")}.`)
        }
        return change("view", view, { reason: reasonOf(event, "trigger-press"), event })
      },
      play(event?: Event) {
        loadedClips("play")
        return change("playing", true, { reason: reasonOf(event, "trigger-press"), event })
      },
      pause(event?: Event) {
        loadedClips("pause")
        return change("playing", false, { reason: reasonOf(event, "trigger-press"), event })
      },
      /** Chooses an animation clip by name; it plays if clips are playing. */
      selectClip(clip: string, event?: Event) {
        const clips = loadedClips("selectClip")
        const match =
          clips.find((name) => name === clip) ?? clips.find((name) => name.toLowerCase() === clip.toLowerCase())
        if (match === undefined) throw new Error(`No clip "${clip}". Clips: ${clips.join(", ")}.`)
        const reason = reasonOf(event, event?.type === "change" ? "input-change" : "trigger-press")
        return change("clip", match, { reason, event })
      },
      /** Whether the clip plays now: the choice made, or by default unless motion is reduced. */
      isPlaying: () => {
        const { playing, reducedMotion } = store.get()
        return playing ?? !reducedMotion
      },
      /** The clip that plays: the chosen one, or the model's first. */
      currentClip: () => {
        const { clip, clips } = store.get()
        return clip !== null && clips.includes(clip) ? clip : (clips[0] ?? null)
      },
      errorMessage: () => context.options().errorMessage,
      clipItems: () => store.get().clips.map((name) => ({ value: name, label: name })),
      /** The scene is loading the model. */
      loading: () => store.set({ status: "loading" }),
      /** The scene has the model, with these clips. */
      loaded: (clips: readonly string[]) => store.set({ status: "ready", clips }),
      failed: () => store.set({ status: "error" }),
      /** A drag or pinch started or ended; auto-rotation waits while it lasts. */
      setDragging: (dragging: boolean) => store.set({ dragging }),
      /** Turns the camera without counting as a person's rotation, for auto-rotation. */
      spin: (degrees: number) => store.set({ yaw: wrapDegrees(store.get().yaw + degrees), motion: "jump" }),
      /** Turns the camera to a view's angles without changing the chosen view, for a scripted move; a jump also resets the zoom. */
      aim,
    }
    return api
  },
  slots: (slot) => ({
    root: slot({
      role: "group",
      attrs: (state) => ({
        "data-status": state.status,
        "aria-busy": state.status === "loading" ? "true" : undefined,
      }),
      bind: (el, part) => {
        const doc = el.ownerDocument
        const win = doc.defaultView
        prepareAnnouncements(doc)
        const motion = win?.matchMedia?.("(prefers-reduced-motion: reduce)")
        const readMotion = () => part.store.set({ reducedMotion: motion?.matches ?? false })
        const readHidden = () => part.store.set({ pageHidden: doc.visibilityState === "hidden" })
        readMotion()
        readHidden()
        if (!supportsWebGL(doc)) part.store.set({ status: "unsupported" })
        motion?.addEventListener("change", readMotion)
        doc.addEventListener("visibilitychange", readHidden)
        // Loads a little before the stage scrolls in, and stops drawing while it's out of view.
        const observer =
          typeof IntersectionObserver === "function"
            ? new IntersectionObserver(
                (entries) => {
                  const inView = entries.some((entry) => entry.isIntersecting)
                  part.store.set(inView ? { inView, seen: true } : { inView })
                },
                { rootMargin: "200px" },
              )
            : undefined
        if (observer) observer.observe(el)
        else part.store.set({ inView: true, seen: true })
        let status = part.store.get().status
        const unsubscribe = part.store.subscribe(() => {
          const state = part.store.get()
          if (state.status === status) return
          status = state.status
          const message = part.api.errorMessage()
          if (status === "error" && message) announce(message, { doc, priority: "assertive" })
        })
        return () => {
          unsubscribe()
          observer?.disconnect()
          motion?.removeEventListener("change", readMotion)
          doc.removeEventListener("visibilitychange", readHidden)
        }
      },
    }),
    stage: slot<{ label: string; describedBy?: string }>({
      props: { label: "string", describedBy: "string" },
      role: "img",
      attrs: (state, part) => ({
        "aria-label": part.props.label,
        "aria-describedby": part.props.describedBy,
        tabindex: state.interactive && state.status === "ready" ? "0" : undefined,
        "data-interactive": state.interactive && state.status === "ready" ? "" : undefined,
        "data-status": state.status,
      }),
      on: {
        keydown: (event, { api, store }) => {
          const { interactive, status } = store.get()
          const key = event as KeyboardEvent
          if (!interactive || status !== "ready" || key.altKey || key.ctrlKey || key.metaKey) return
          const turns: Record<string, [number, number]> = {
            ArrowLeft: [-keyStep, 0],
            ArrowRight: [keyStep, 0],
            ArrowUp: [0, -keyStep],
            ArrowDown: [0, keyStep],
          }
          const turn = turns[key.key]
          if (turn) api.rotate(turn[0], turn[1], event)
          else if (key.key in zoomKeys) api.zoom(zoomKeys[key.key] ?? 0, event)
          else if (key.key === "Home") api.reset(event)
          else return
          event.preventDefault()
        },
      },
      bind: (el, part) => {
        const pointers = new Map<number, { x: number; y: number }>()
        let spread = 0
        const distance = () => {
          const [a, b] = [...pointers.values()]
          return a && b ? Math.hypot(a.x - b.x, a.y - b.y) : 0
        }
        const active = () => {
          const { interactive, status } = part.store.get()
          return interactive && status === "ready"
        }
        const down = (event: PointerEvent) => {
          if (!active() || (event.pointerType === "mouse" && event.button !== 0)) return
          el.setPointerCapture?.(event.pointerId)
          pointers.set(event.pointerId, { x: event.clientX, y: event.clientY })
          spread = distance()
          part.api.setDragging(true)
        }
        const moveTo = (event: PointerEvent) => {
          const last = pointers.get(event.pointerId)
          if (!last) return
          const dx = event.clientX - last.x
          const dy = event.clientY - last.y
          pointers.set(event.pointerId, { x: event.clientX, y: event.clientY })
          if (pointers.size === 1) {
            if (dx !== 0 || dy !== 0) part.api.rotate(dx * dragStep, dy * dragStep, event)
            return
          }
          const next = distance()
          if (spread > 0 && next > 0) part.api.zoom(Math.log(next / spread) / Math.log(zoomStep), event)
          spread = next
        }
        const up = (event: PointerEvent) => {
          if (!pointers.delete(event.pointerId)) return
          spread = distance()
          if (pointers.size === 0) part.api.setDragging(false)
        }
        const wheel = (event: WheelEvent) => {
          if (!active()) return
          event.preventDefault()
          part.api.zoom(-event.deltaY / 240, event)
        }
        el.addEventListener("pointerdown", down)
        el.addEventListener("pointermove", moveTo)
        el.addEventListener("pointerup", up)
        el.addEventListener("pointercancel", up)
        el.addEventListener("wheel", wheel, { passive: false })
        return () => {
          el.removeEventListener("pointerdown", down)
          el.removeEventListener("pointermove", moveTo)
          el.removeEventListener("pointerup", up)
          el.removeEventListener("pointercancel", up)
          el.removeEventListener("wheel", wheel)
        }
      },
    }),
    poster: slot({
      attrs: (state) => ({ "aria-hidden": "true", "data-status": state.status }),
    }),
    canvas: slot({
      present: (state) => state.status !== "unsupported" && state.load && state.seen,
      attrs: (state) => ({ "aria-hidden": "true", "data-status": state.status }),
    }),
    message: slot<{}, { status: ModelViewerStatus }>({
      state: (state) => ({ status: state.status }),
      present: (state) => state.status === "unsupported" || state.status === "error",
      attrs: (state) => ({ "data-status": state.status }),
    }),
    controls: slot<{ label?: string }, ModelViewerControlsState>({
      props: { label: "string" },
      role: "group",
      state: (state) => ({
        status: state.status,
        view: state.view,
        clips: state.clips,
        clip: state.clip !== null && state.clips.includes(state.clip) ? state.clip : (state.clips[0] ?? null),
        playing: state.playing ?? !state.reducedMotion,
      }),
      present: (state) => state.interactive && state.status !== "unsupported",
      attrs: (state, part) => ({
        "aria-label": part.props.label,
        "data-status": state.status,
      }),
    }),
  }),
  agent: {
    actions: ["rotate", "zoom", "reset", "setView", "play", "pause", "selectClip"],
    items: (api) => api.clipItems(),
  },
})

type ModelViewerState = TypesOf<typeof modelViewer>["state"]

/** The viewer's state and api, as the scene reads them each frame. */
type ModelViewerHandle = {
  get: () => ModelViewerState
  subscribe: (listener: () => void) => () => void
  api: TypesOf<typeof modelViewer>["api"]
}

export { modelViewer }
export type {
  ModelViewerHandle,
  ModelViewerState,
  ModelViewerChangeReason,
  ModelViewerControlsState,
  ModelViewerMotion,
  ModelViewerOptions,
  ModelViewerStatus,
}

import { createContext } from "react"
import {
  AnimationMixer,
  Box3,
  DataTexture,
  LoopOnce,
  LoopRepeat,
  Mesh,
  MeshToonMaterial,
  NearestFilter,
  RedFormat,
  Vector3,
  type AnimationAction,
  type AnimationClip,
  type Material,
  type MeshStandardMaterial,
  type Object3D,
  type PerspectiveCamera,
} from "three"

import {
  damp,
  dampWeights,
  fitBoxDistance,
  fitSphereDistance,
  orbitPosition,
  type ModelViewerFraming,
  type WeightMap,
} from "@/components/ui/model-viewer-math"
import type { ModelViewerHandle } from "@/components/ui/model-viewer-primitive"

type LoadedModel = { scene: Object3D; animations: readonly AnimationClip[] }

type ModelViewerMaterial = "standard" | "toon"

type RigInput = {
  handle: ModelViewerHandle
  camera: PerspectiveCamera
  framing: ModelViewerFraming
  loop: boolean
  speed: number
  /** Degrees per second; 0 holds still. */
  autoRotate: number
}

// Per second: the camera eases over about a second and a half, weights over about a third of one.
const cameraRate = 4
const weightRate = 10
const clipFade = 0.3

const angleEpsilon = 0.02
const relativeEpsilon = 1e-4

type MorphMesh = Mesh & { morphTargetDictionary: Record<string, number>; morphTargetInfluences: number[] }

const isMesh = (object: Object3D): object is Mesh => (object as Mesh).isMesh === true

/** Three tones of light, read nearest, for the toon look. */
function toonGradient() {
  const texture = new DataTexture(new Uint8Array([90, 170, 255]), 3, 1, RedFormat)
  texture.minFilter = NearestFilter
  texture.magFilter = NearestFilter
  texture.generateMipmaps = false
  texture.needsUpdate = true
  return texture
}

function toonOf(material: Material, gradientMap: DataTexture) {
  const source = material as MeshStandardMaterial
  return new MeshToonMaterial({
    name: material.name,
    color: source.color,
    map: source.map ?? null,
    vertexColors: source.vertexColors,
    transparent: source.transparent,
    opacity: source.opacity,
    side: source.side,
    gradientMap,
  })
}

/**
 * Everything a loaded model does per frame, outside React: the camera eased to the orbit the primitive holds, morph
 * weights eased to their targets, and the animation mixer. `update` says whether it needs another frame, so the
 * canvas draws only while something moves.
 */
function createModelRig(model: LoadedModel) {
  const box = new Box3().setFromObject(model.scene)
  const size = box.getSize(new Vector3())
  const boxCenter = box.getCenter(new Vector3())
  const meshes: MorphMesh[] = []
  const surfaces: Mesh[] = []
  model.scene.traverse((object) => {
    if (!isMesh(object)) return
    surfaces.push(object)
    if (object.morphTargetDictionary && object.morphTargetInfluences) meshes.push(object as MorphMesh)
  })
  const morphNames = [...new Set(meshes.flatMap((mesh) => Object.keys(mesh.morphTargetDictionary)))]
  const clipNames = model.animations.map((clip) => clip.name)
  const mixer = new AnimationMixer(model.scene)
  const actions = new Map<string, AnimationAction>()
  for (const clip of model.animations) actions.set(clip.name, mixer.clipAction(clip as AnimationClip))

  const originals = new Map(surfaces.map((mesh) => [mesh, mesh.material]))
  let gradient: DataTexture | undefined
  const toons = new Map<Material, MeshToonMaterial>()
  let material: ModelViewerMaterial = "standard"
  let opacity = 1

  let weights: WeightMap = {}
  let targetWeights: WeightMap = {}
  let weightsSettled = true

  const camera = { yaw: 0, pitch: 0, zoom: 1, distance: 0, turn: -1, ready: false }
  const center = new Vector3()
  const goalCenter = new Vector3()
  let settled = false
  let activeClip: string | null = null
  let wasPlaying = false

  const applyWeights = () => {
    for (const mesh of meshes) {
      for (const [name, value] of Object.entries(weights)) {
        const index = mesh.morphTargetDictionary[name]
        if (index !== undefined) mesh.morphTargetInfluences[index] = value
      }
    }
  }

  const eachMaterial = (run: (material: Material) => void) => {
    for (const mesh of surfaces) for (const item of [mesh.material].flat()) run(item)
  }

  const applyOpacity = () => {
    eachMaterial((item) => {
      item.transparent = opacity < 1
      item.opacity = opacity
      item.depthWrite = opacity >= 1
      item.needsUpdate = true
    })
  }

  const rig = {
    scene: model.scene,
    morphNames,
    clipNames,
    /** The box's centre and size, in the model's units. */
    bounds: { center: boxCenter, size },
    /** New target weights; `immediate` jumps to them, like the first weights of a model. */
    setWeights(next: WeightMap, immediate = false) {
      targetWeights = next
      weightsSettled = false
      if (immediate) {
        weights = dampWeights(weights, next, weightRate, Number.POSITIVE_INFINITY).next
        weightsSettled = true
        applyWeights()
      }
    },
    setMaterial(next: ModelViewerMaterial) {
      if (next === material) return
      material = next
      if (next === "toon") gradient ??= toonGradient()
      for (const mesh of surfaces) {
        const original = originals.get(mesh) ?? mesh.material
        if (next === "standard") {
          mesh.material = original
          continue
        }
        const swap = (item: Material) => {
          let toon = toons.get(item)
          if (!toon) {
            toon = toonOf(item, gradient as DataTexture)
            toons.set(item, toon)
          }
          return toon
        }
        mesh.material = Array.isArray(original) ? original.map(swap) : swap(original)
      }
      applyOpacity()
    },
    /** Fades the whole model, for a reveal. */
    setOpacity(next: number) {
      if (next === opacity) return
      opacity = next
      applyOpacity()
    },
    /** Where the camera looks and how far it stands at zoom 1, for the current framing and aspect. */
    frame(framing: ModelViewerFraming, view: PerspectiveCamera) {
      if (framing === "full") {
        return { center: boxCenter, distance: fitBoxDistance([size.x, size.y, size.z], view.fov, view.aspect) }
      }
      return {
        center: new Vector3(...framing.center),
        distance: fitSphereDistance(framing.radius, view.fov, view.aspect),
      }
    },
    /** Moves everything one frame on; true while something still moves. */
    update(dt: number, input: RigInput) {
      const { handle, camera: view } = input
      const state = handle.get()
      const jump = state.reducedMotion
      let moving = false

      if (input.autoRotate !== 0 && !state.reducedMotion && !state.dragging && state.status === "ready") {
        handle.api.spin(input.autoRotate * dt)
        moving = true
      }

      const framed = rig.frame(input.framing, view)
      goalCenter.copy(framed.center)
      if (!camera.ready || state.turn !== camera.turn) {
        if (!camera.ready || state.motion === "jump") {
          camera.yaw = state.yaw
          camera.pitch = state.pitch
          camera.zoom = state.zoom
        }
        if (!camera.ready) {
          center.copy(goalCenter)
          camera.distance = framed.distance
        }
        camera.turn = state.turn
        camera.ready = true
        settled = false
      }
      const step = (from: number, to: number, epsilon: number) => {
        if (jump || Math.abs(from - to) < epsilon) return to
        moving = true
        return damp(from, to, cameraRate, dt)
      }
      const before = moving
      moving = false
      camera.yaw = step(camera.yaw, state.yaw, angleEpsilon)
      camera.pitch = step(camera.pitch, state.pitch, angleEpsilon)
      camera.zoom = step(camera.zoom, state.zoom, relativeEpsilon)
      camera.distance = step(camera.distance, framed.distance, framed.distance * relativeEpsilon)
      center.set(
        step(center.x, goalCenter.x, camera.distance * relativeEpsilon),
        step(center.y, goalCenter.y, camera.distance * relativeEpsilon),
        step(center.z, goalCenter.z, camera.distance * relativeEpsilon),
      )
      const cameraMoving = moving
      moving = before || cameraMoving
      const distance = camera.distance / camera.zoom
      const [x, y, z] = orbitPosition([center.x, center.y, center.z], camera.yaw, camera.pitch, distance)
      view.position.set(x, y, z)
      view.lookAt(center)
      const near = distance / 100
      if (Math.abs(view.near - near) > near * 0.1) {
        view.near = near
        view.far = distance * 100
        view.updateProjectionMatrix()
      }

      const clip = handle.api.currentClip()
      const playing = handle.api.isPlaying()
      if (clip !== activeClip) {
        const previous = activeClip ? actions.get(activeClip) : undefined
        const next = clip ? actions.get(clip) : undefined
        const fade = state.reducedMotion || !previous ? 0 : clipFade
        if (previous) previous.fadeOut(fade)
        if (next) next.reset().fadeIn(fade).play()
        activeClip = clip
        mixer.update(0)
      }
      const action = activeClip ? actions.get(activeClip) : undefined
      if (action) {
        action.setLoop(input.loop ? LoopRepeat : LoopOnce, Number.POSITIVE_INFINITY)
        action.clampWhenFinished = true
        action.paused = !playing
        if (playing && !wasPlaying && !action.isRunning() && action.time >= action.getClip().duration) action.reset()
        mixer.timeScale = input.speed
        if (playing && (action.isRunning() || action.getEffectiveWeight() < 1)) {
          mixer.update(dt)
          moving = true
        }
      }
      wasPlaying = playing

      if (!weightsSettled) {
        const result = dampWeights(weights, targetWeights, weightRate, dt)
        weights = result.next
        weightsSettled = result.settled
        moving = true
      }
      applyWeights()

      // The camera reports where it came to rest, even while a clip keeps the frames coming.
      const justSettled = !cameraMoving && !settled
      if (!cameraMoving) settled = true
      return { moving, justSettled, camera: { yaw: camera.yaw, pitch: camera.pitch, zoom: camera.zoom } }
    },
    dispose(owned: boolean) {
      mixer.stopAllAction()
      mixer.uncacheRoot(model.scene)
      for (const toon of toons.values()) toon.dispose()
      gradient?.dispose()
      if (!owned) return
      model.scene.traverse((object) => {
        if (!isMesh(object)) return
        object.geometry.dispose()
        for (const item of [object.material].flat()) {
          for (const value of Object.values(item))
            if (value && typeof value === "object" && "isTexture" in value) value.dispose()
          item.dispose()
        }
      })
    },
  }
  return rig
}

